```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
void generatePermutations(const std::string &input, int length, std::vector<std::string> &perms) {
    if (length == input.size()) {
        perms.push_back(input);
        return;
    }
    std::string str(input);
    for (int i = 0; i < input.size(); ++i) {
        swap(str[i], str[length]);
        generatePermutations(str, length + 1, perms);
        swap(str[i], str[length]);
    }
}
