 Here's an example implementation of `RedisClient` class in Node.js using the `redis` package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This implementation covers all the required functions for your `RedisClient` class. The `RedisClient` constructor initializes a new Redis client and sets up an error event listener. The `isAlive` method checks whether the connection to Redis is successful or not. The `get`, `set`, and `del` methods are asynchronous and use callbacks with Promises for easier usage. Finally, an instance of `RedisClient` named `redisClient` is created and exported from the module.

