 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Create a slice of specific negative words.
2. Split the given sentence into words.
3. Iterate through each word in the sentence.
4. Check if the current word is in the slice of negative words or if the next word is "not" followed by a negative word.
5. If either condition is true, increment a counter.
6. After iterating through all the words, if the counter is greater than zero, print a message indicating that the sentence contains a double negative.

Here's an example Go code implementation:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "am not", "aren't", "isn't", "doesn't", "don't", "haven't", "hasn't", "hadn't", "won't", "wouldn't", "can't", "couldn't", "shall not", "shouldn't", "may not", "might not", "must not"}
	sentence := "He isn't not worried about the coronavirus situation"
	counter := 0
	words := strings.Split(sentence, " ")

	for i := 0; i < len(words)-1; i++ {
		currentWord := words[i]
		nextWord := words[i+1]
		if containsNegativeWord(currentWord) || (nextWord == "not" && containsNegativeWord(words[i+1])) {
			counter++
		}
	}

	if counter > 0 {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord {
			return true
		}
	}
	return false
}
```

