 I'd be happy to help you write a PowerShell script that checks the Access Control Lists (ACLs) of folders recursively for Security Identifiers (SIDs) that occur only in the SIDHistory of any user or group in the Active Directory domain. Here's an example of how you can achieve this using PowerShell and the `System.Security.Principal.SecurityIdentifier` class from .NET:

```powershell
# Import required modules
Import-Module ActiveDirectory
Add-Type -AssemblyName System.IdentityModel.Tokens

# Function to get all users and groups with SIDHistory
function Get-ADObjectWithSIDHistory {
    $Filter = 'objectClass -eq "user" -or objectClass -eq "group" -and msDS-ManagedBy -ne "$null"'
    $Searcher = New-Object System.Directory.Searcher
    $Searcher.Filter = $Filter
    $Searcher.SearchRoot = [ADSI]"LDAP://DC=domain,DC=com"

    $Results = @()

    do {
        $Result = $Searcher.FindOne()

        if ($Result -ne $null) {
            $SIDHistory = New-Object System.Security.Principal.SecurityIdentifier($Result.Properties['msDS-ManagedBy'][0].Value).Value
            $Results += New-Object PSObject -Property @{
                Name     = $Result.Properties['name'][0].Value
                SID      = $SIDHistory
                Path     = $Result.DistinguishedName
            }
            $Searcher.Filter = $Filter -and "(msDS-ManagedBy=$($Result.DistinguishedName))"
        }
    } while ($Result -ne $null)

    return $Results
}

